<script setup lang="ts">
import { computed, ref, watch } from "vue";
import { useI18n } from "vue-i18n";
import type { createOnlineStore } from "../../stores/online.js";
import type { createOnlineProjectAdapter } from "../../stores/onlineProjectAdapter.js";
import type { ApiRequest, ContractProject, JsonValue, Workflow } from "@apicc/core";
import { ProjectRelativePathSchema } from "@apicc/execution/contract";
import { buildBindIndex, type WfBindIndex } from "../../wf/wfBindings.js";
import EnvPanel from "../EnvPanel.vue";
import DatasetPanel from "../DatasetPanel.vue";
import SuitePanel from "../SuitePanel.vue";
import WfDesigner from "../WfDesigner.vue";
import CasePanel from "../CasePanel.vue";
import CredentialEditor from "../CredentialEditor.vue";
import OnlineExecutionPanel from "./OnlineExecutionPanel.vue";
const props = defineProps<{ online: ReturnType<typeof createOnlineStore>; adapter: ReturnType<typeof createOnlineProjectAdapter>; localProjects: Array<{ label: string; project: ContractProject }> }>();
const { t } = useI18n();
const pane = ref("api"); const datasetName = ref(""); const suiteName = ref(""); const selectedApi = ref(""); const publishSource = ref("");
const attachmentRef = ref(''); const attachmentPath = ref(''); const attachmentId = ref(''); const attachmentKind = ref<'file' | 'network-public'>('file');
async function upload(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; const context = JSON.stringify(execution.value.context); if (!file || readOnly.value) return; const policy = execution.value.agents?.policy; if (!attachmentRef.value || file.size > (policy?.singleAttachmentBytes ?? 0)) throw new Error('input-capacity-exceeded'); const contentBase64 = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onerror = () => reject(new Error('attachment-read-failed')); reader.onload = () => resolve(String(reader.result).split(',', 2)[1] ?? ''); reader.readAsDataURL(file); }); if (context !== JSON.stringify(execution.value.context)) return; const existing = execution.value.materialMetadata?.attachments.find(item => item.refId === attachmentRef.value); await execution.value.uploadAttachment({ refId: attachmentRef.value, expectedVersion: existing?.version ?? '0', kind: attachmentKind.value, contentBase64 }); }
const execution = computed(() => props.online.execution);
const materialCredentials = computed(() => execution.value.materialMetadata?.credentials.map(credential => ({ ...credential, status: t(`contract.credentialStatus.${credential.status}`) })));
const entries = computed(() => execution.value.project ? props.adapter.apiEntries() : []);
const bindIndex = ref<WfBindIndex | null>(null);
const readOnly = computed(() => !execution.value.context || !props.online.canEdit(`${execution.value.context.scope.projectId}/project.yaml`));
function reportError(error: unknown) { execution.value.error = error instanceof Error ? error.message : String(error); }
async function action(operation: () => unknown | Promise<unknown>) { const scope = JSON.stringify(execution.value.context); try { await operation(); } catch (error) { if (scope === JSON.stringify(execution.value.context) && execution.value.visible) reportError(error); } }
watch(() => [execution.value.context, execution.value.view?.assets.version], async () => { if (!execution.value.project) { bindIndex.value = null; return; } const captured = JSON.stringify(execution.value.context); const result = await buildBindIndex(props.adapter.workspace.tree, props.adapter.locator(), props.adapter.bridge.apiGet); if (captured === JSON.stringify(execution.value.context)) bindIndex.value = result; }, { immediate: true });
async function pickApi(id: string) { selectedApi.value = id; const entry = entries.value.find(entry => entry.asset.contract.id === id); if (entry) await props.adapter.editor.load(entry.locator); }
async function debugRequest() {
  const request = props.online.editorApi?.contract.request; const entry = entries.value.find(entry => entry.asset.contract.id === props.online.editorApi?.contract.id);
  if (!request || !entry) throw new Error("online-project-unavailable");
  await execution.value.run({ kind: "debug", invocation: { mode: "request", locator: entry.locator, request, parameters: {}, fields: [], ...(execution.value.environmentId ? { environmentId: execution.value.environmentId } : {}) } });
}
async function workflowRun(workflow: Workflow, inputs?: Readonly<Record<string, JsonValue>>) { if (props.adapter.workflowDesign.dirty) throw new Error("save-before-running"); await execution.value.run({ kind: "workflow", workflowId: workflow.id, ...(inputs ? { inputs: { ...inputs } } : {}) }); }
async function suiteRun(allowDraft: boolean) { if (!props.adapter.testing.suite || props.adapter.testing.dirty) throw new Error("save-before-running"); await execution.value.run({ kind: "suite", suiteId: props.adapter.testing.suite.id, allowDraft }); }
const auth = computed(() => props.online.editorApi?.contract.request.auth);
function authKind(value: string) { const request = props.online.editorApi?.contract.request; if (!request || readOnly.value) return; request.auth = value === "bearer" ? { kind: "bearer", token: { id: "project-token", policy: "test-auto" } } : value === "basic" ? { kind: "basic", username: "", password: { id: "project-password", policy: "test-auto" } } : value === "apikey" ? { kind: "apikey", name: "X-API-Key", placement: "header", value: { id: "project-api-key", policy: "test-auto" } } : { kind: "none" }; }
const credentialRef = computed(() => auth.value?.kind === "bearer" ? auth.value.token : auth.value?.kind === "basic" ? auth.value.password : auth.value?.kind === "apikey" ? auth.value.value : null);
function localOnly(checked: boolean) { const id = credentialRef.value?.id; if (!id) return; execution.value.localOnlyRefIds = checked ? [...new Set([...execution.value.localOnlyRefIds, id])] : execution.value.localOnlyRefIds.filter(ref => ref !== id); }
const emit = defineEmits<{ published: [projectId: string] }>();
async function publish() { const item = props.localProjects.find(item => item.project.id === publishSource.value); const context = execution.value.context; if (!item || !context) return; const captured = JSON.stringify(context); const result = await props.adapter.bridge.onlineExecution({ operation: "publishNew", context, name: item.project.name, project: item.project }); if (captured !== JSON.stringify(execution.value.context)) return; if (typeof result === 'object' && result !== null && 'scope' in result && 'view' in result) { await props.online.refreshTreeView(); emit('published', result.scope.projectId); } }
async function selectOnlineApi(id: string) { const path = execution.value.view?.assets.files.find(file => file.path.endsWith(`/apis/${id}/api.yaml`))?.path; if (path && execution.value.context) await props.online.selectNode('api', `${execution.value.context.scope.projectId}/${path}`, { force: true }); }
</script>
<template>
  <section class="online-project" data-testid="online-project-assets">
    <OnlineExecutionPanel :execution="execution" />
    <p v-if="execution.busy">{{ t('onlineExecution.loading') }}</p>
    <section v-else-if="!execution.project" class="legacy" data-testid="online-legacy-limitation"><template v-if="execution.view"><p>{{ t('onlineExecution.legacy') }}</p><ul><li v-for="problem in execution.view.problems" :key="problem">{{ problem === 'legacy-format-publish-new-project' ? t('onlineExecution.legacy') : problem }}</li></ul><p>{{ t('onlineExecution.publishEmpty') }}</p><select v-model="publishSource"><option value="">{{ t('onlineExecution.localProject') }}</option><option v-for="item in localProjects" :key="item.project.id" :value="item.project.id">{{ item.label }}</option></select><button :disabled="!publishSource || readOnly" @click="action(publish)">{{ t('onlineExecution.publish') }}</button></template><p v-else>{{ t('onlineExecution.notCollected') }}</p></section>
    <template v-else>
      <nav class="tabs"><button v-for="tab in ['api','cases','environments','datasets','suites','workflows','auth','materials']" :key="tab" :class="{ active: pane === tab }" @click="pane = tab">{{ t('onlineExecution.panes.' + tab) }}</button></nav>
      <div class="asset-scroll">
        <template v-if="pane === 'api'"><select :value="online.editorApi?.contract.id ?? ''" @change="action(() => selectOnlineApi(($event.target as HTMLSelectElement).value))"><option value="">{{ t('onlineExecution.pickApi') }}</option><option v-for="entry in entries" :key="entry.asset.contract.id" :value="entry.asset.contract.id">{{ entry.asset.contract.metadata.name }}</option></select><button :disabled="!online.editorApi || execution.running || readOnly" data-testid="online-debug-run" @click="action(debugRequest)">{{ t('onlineExecution.debug') }}</button><slot /></template>
        <template v-else-if="pane === 'cases'"><select :value="selectedApi" @change="action(() => pickApi(($event.target as HTMLSelectElement).value))"><option value="">{{ t('onlineExecution.pickApi') }}</option><option v-for="entry in entries" :key="entry.asset.contract.id" :value="entry.asset.contract.id">{{ entry.asset.contract.metadata.name }}</option></select><CasePanel :editor="adapter.editor" :cases="adapter.cases" :read-only="readOnly" :datasets="execution.project.datasets" :operators="adapter.testing.operators" :report-error="reportError" /><button :disabled="!adapter.cases.selectedCase || readOnly || adapter.editor.dirty" @click="action(async () => { const locator = adapter.editor.locator; const selected = adapter.cases.selectedCase; if (locator && selected) await execution.run({ kind: 'debug', invocation: { mode: 'case', locator, case: { ...locator, ...selected }, environmentId: execution.environmentId } }); })">{{ t('onlineExecution.runCase') }}</button></template>
        <EnvPanel v-else-if="pane === 'environments'" :envs="adapter.envs" :workspace="adapter.workspace" :project-locator="adapter.locator()" :report-error="reportError" />
        <template v-else-if="pane === 'datasets'"><div class="toolbar"><select :value="adapter.testing.dataset?.id ?? ''" @change="action(() => adapter.testing.select('dataset', ($event.target as HTMLSelectElement).value))"><option value="">{{ t('testing.pickDataset') }}</option><option v-for="item in execution.project.datasets" :key="item.id" :value="item.id">{{ item.name }}</option></select><input v-model="datasetName" :placeholder="t('testing.name')" /><button :disabled="readOnly || !datasetName" @click="action(() => adapter.testing.newDataset(datasetName))">{{ t('testing.newDataset') }}</button></div><DatasetPanel :testing="adapter.testing" /></template>
        <template v-else-if="pane === 'suites'"><div class="toolbar"><select :value="adapter.testing.suite?.id ?? ''" @change="action(() => adapter.testing.select('suite', ($event.target as HTMLSelectElement).value))"><option value="">{{ t('testing.pickSuite') }}</option><option v-for="item in execution.project.suites" :key="item.id" :value="item.id">{{ item.name }}</option></select><input v-model="suiteName" :placeholder="t('testing.name')" /><button :disabled="readOnly || !suiteName" @click="action(() => adapter.testing.newSuite(suiteName))">{{ t('testing.newSuite') }}</button></div><SuitePanel :testing="adapter.testing" :external-run="suiteRun" /></template>
        <WfDesigner v-else-if="pane === 'workflows'" :workflow-design="adapter.workflowDesign" :wf-list="adapter.wfList" :workspace="adapter.workspace" :project-locator="adapter.locator()" :bind-index="bindIndex" :report-error="reportError" :external-run="workflowRun" />
        <section v-else-if="pane === 'materials'" class="auth"><p>{{ t('onlineExecution.attachmentHint') }}</p><label>{{ t('onlineExecution.attachmentRef') }}<input v-model="attachmentRef" :disabled="readOnly" /></label><select v-model="attachmentKind" :disabled="readOnly"><option value="file">{{ t('onlineExecution.file') }}</option><option value="network-public">{{ t('onlineExecution.networkPublic') }}</option></select><label>{{ t('onlineExecution.upload') }}<input type="file" :disabled="readOnly || !attachmentRef" @change="action(() => upload($event))" /></label><table><thead><tr><th>{{ t('onlineExecution.refId') }}</th><th>{{ t('onlineExecution.version') }}</th><th>{{ t('onlineExecution.materialState') }}</th></tr></thead><tbody><tr v-for="credential in materialCredentials" :key="credential.refId"><td>{{ credential.refId }}</td><td>{{ credential.version }}</td><td>{{ credential.status }}</td></tr></tbody></table><table><thead><tr><th>{{ t('onlineExecution.attachmentRef') }}</th><th>{{ t('onlineExecution.version') }}</th><th>{{ t('onlineExecution.bytes') }}</th></tr></thead><tbody><tr v-for="attachment in execution.materialMetadata?.attachments" :key="attachment.refId"><td>{{ attachment.refId }}</td><td>{{ attachment.version }}</td><td>{{ attachment.size }}</td></tr></tbody></table><label>{{ t('onlineExecution.attachmentPath') }}<input v-model="attachmentPath" /></label><select v-model="attachmentId"><option value="">{{ t('onlineExecution.attachmentRef') }}</option><option v-for="attachment in execution.materialMetadata?.attachments" :key="attachment.refId" :value="attachment.refId">{{ attachment.refId }}</option></select><button :disabled="readOnly || !attachmentPath || !attachmentId" @click="action(async () => execution.bindAttachment(ProjectRelativePathSchema.parse(attachmentPath), attachmentId))">{{ t('onlineExecution.bindAttachment') }}</button><ul><li v-for="(ref, path) in execution.materials.attachmentPaths" :key="path">{{ path }} → {{ ref.refId }} · {{ ref.version }}</li></ul></section>
        <section v-else-if="pane === 'auth'" class="auth"><p>{{ t('onlineExecution.authInProject') }}</p><p v-if="!auth">{{ t('onlineExecution.pickApi') }}</p><template v-else><select :value="auth.kind" :disabled="readOnly" @change="authKind(($event.target as HTMLSelectElement).value)"><option value="none">{{ t('online.authNone') }}</option><option value="bearer">Bearer</option><option value="basic">Basic</option><option value="apikey">API Key</option><option v-if="auth.kind === 'componentRef'" value="componentRef">{{ t('online.authComponent') }}</option></select><label v-if="credentialRef">{{ t('onlineExecution.refId') }}<input v-model="credentialRef.id" :disabled="readOnly" /></label><label v-if="auth.kind === 'basic'">{{ t('onlineExecution.username') }}<input v-model="auth.username" :disabled="readOnly" /></label><template v-if="auth.kind === 'apikey'"><label>{{ t('onlineExecution.keyName') }}<input v-model="auth.name" :disabled="readOnly" /></label><select v-model="auth.placement" :disabled="readOnly"><option value="header">Header</option><option value="query">Query</option></select></template><button :disabled="readOnly" @click="action(() => online.saveApi())">{{ t('onlineExecution.saveAuth') }}</button><label v-if="credentialRef"><input type="checkbox" :checked="execution.localOnlyRefIds.includes(credentialRef.id)" :disabled="readOnly" @change="localOnly(($event.target as HTMLInputElement).checked)" />{{ t('onlineExecution.localOnly') }}</label><CredentialEditor v-if="credentialRef" :api="adapter.bridge" :locator="adapter.locator()" :auth="auth" :context-key="JSON.stringify([execution.context, execution.localOnlyRefIds])" managed-state="unmanaged" :read-only="readOnly" /></template></section>
      </div>
    </template>
  </section>
</template>
<style scoped>
.online-project{height:100%;min-height:0;min-width:0;display:flex;flex-direction:column;overflow:auto}.tabs{display:flex;gap:5px;flex-wrap:wrap;padding:8px;border-bottom:1px solid var(--border)}.tabs .active{color:var(--accent);border-color:var(--accent)}.asset-scroll{flex:1;min-height:340px;overflow:auto}.toolbar{display:flex;gap:8px;padding:8px;flex-wrap:wrap}.auth,.legacy{padding:12px}.auth label{display:flex;gap:8px;margin:8px 0}.legacy p{max-width:75ch}
</style>
